  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 10px;
  background: #ffffff;
  overflow: hidden;
  margin: 0 auto;
  flex-direction: column;
}

.title {
    font-size: 20px;
    line-height: 24px;
    font-weight: 600;
    margin-bottom: 90px;
    color: #1A1A1A;
}

.subtitle {
  margin-bottom: 0;
}

.buttons {
  display: flex;
  flex-direction: row;
  gap: 8px;
  margin-bottom: 40px;
}

.info {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.infoContent {
  display: flex;
  flex-direction: column;
