/* Новые стили для иконок в полях */
.inputRow {
  position: relative;
  display: flex;
  align-items: center;
}

.icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #9AA0A6; /* цвет иконки */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

/* Класс, который передаётся в Input через prop className */
/* Увеличиваем левый padding, чтобы иконка не перекрывала текст */
.input {
  padding-left: 40px;
  width: 100%;
  box-sizing: border-box;
}
